// @splicewire/beam-docs — the OpenAPI reference surface (ADR-0210 §5), named for its ROLE and not
// its vendor. Scalar is today's renderer; swapping it is an edit inside THIS file rather than an edit
// to every seeded page body, which is the entire reason the component is not called `<Scalar>`.
//
// It points at a spec URL — normally the core-mounted `beam/openapi.json` (ADR-0211) served by the
// host's OWN routes, because a beam site documents ITSELF rather than mirroring one upstream spec.
//
// ── The CDN cost, resolved ───────────────────────────────────────────────────────────────────────
// The incumbent (splicewire-app's `docs/index.blade.php`) loaded Scalar from `cdn.jsdelivr.net` at
// runtime, which an air-gapped or CSP-strict install cannot do. Bundling Scalar instead was rejected:
// it is a multi-megabyte renderer, and beam-ux is imported by hosts that never open an API reference
// — every one of them would pay for it. So the loader is kept and made SEAM-SHAPED, matching the rest
// of the package's injection posture:
//
//   - default          → the CDN script, exactly as the incumbent (nothing to configure, still works),
//   - `scriptUrl`      → the same loader pointed at a self-hosted / vendored copy (CSP allow-list),
//   - `createApiReference` → an injected factory: a host that installs `@scalar/api-reference` itself
//     passes its `createApiReference` and NOTHING is fetched from the network at all (air-gapped).
//
// ── Theme ────────────────────────────────────────────────────────────────────────────────────────
// The package ships no palette and no fonts. The incumbent's brand block (Space Grotesk / IBM Plex
// Mono, the two accent colors) is HOST-LOCAL and arrives through `customCss` — a theme prop. What IS
// baked in is the curation, not a look: Scalar's vendor badge is removed, and
// `.scalar-mcp-layer { display: none }` because a beam site's MCP surface has its OWN docs page (the
// `<ManifestTable>` one) and Scalar's auto "Generate MCP" affordance would compete with it.
// `hideMcpLayer={false}` opts out of the MCP curation only.
import { useAppearance } from '@splicewire/beam-ux/appearance';
import { useEffect, useRef, useState } from 'react';
import type { CSSProperties } from 'react';
import { docsConfiguration } from './config.js';
import { fetchDocs, fetchRegistryLink, scalarRegistryUrl, type DocsTransport } from './publications.js';

/** The Scalar entry point this component drives. Structural — we never import the package. */
export type ApiReferenceFactory = (
    selectorOrElement: string | HTMLElement,
    configuration: Record<string, unknown>,
) => unknown;

/** The pinned Scalar release the default CDN source serves. */
const SCALAR_VERSION = '1.65.1';

/**
 * Subresource Integrity for each pinned release's `dist/browser/standalone.js` (self-contained, no lazy chunks), the
 * sha384 of the npm tarball's own file, which jsDelivr serves byte for byte. Keyed by version so bumping
 * {@link SCALAR_VERSION} without adding its hash fails the type check (DOCS-13 review: pinning stops drift, SRI stops a
 * replaced file).
 */
const SCALAR_SRI = {
    '1.65.1': 'sha384-G6dkutu2k5IYVyNESLoFIpgaHx38IJTZ/HhrwN0fecTle9te75y8Kru3rJEJ0ZJV',
} as const satisfies Record<typeof SCALAR_VERSION, `sha384-${string}`>;

/** The default CDN source. Exported so a host can pin or re-host from it. */
export const SCALAR_CDN_URL = `https://cdn.jsdelivr.net/npm/@scalar/api-reference@${SCALAR_VERSION}/dist/browser/standalone.js`;

/** The integrity the default source is loaded with; a host's own `scriptUrl` carries none (its bytes are its own). */
export const SCALAR_CDN_INTEGRITY: string = SCALAR_SRI[SCALAR_VERSION];

/** A lazy loader resolving a factory (the flagship code-splits its patched local Scalar). */
export type ApiReferenceLoader = () => Promise<ApiReferenceFactory>;

/**
 * The PALETTE (docs-walkthrough DM5, DOCS-13): Scalar's variables read the ONE --beam-* token family, which flips under
 * `.dark`, so the reference matches the guides in both schemes and no host themes Scalar itself (D-T2). Host hooks come
 * first, then the defined beam-ux tokens.
 */
export const BEAM_SCALAR_CSS = `.scalar-app {
  --scalar-background-1: var(--beam-paper-raised, var(--beam-paper));
  --scalar-background-2: var(--beam-surface-2, var(--beam-muted));
  --scalar-background-3: var(--beam-surface-2, var(--beam-muted));
  --scalar-color-1: var(--beam-fg, var(--beam-ink));
  --scalar-color-2: var(--beam-fg-muted, var(--beam-ink-muted));
  --scalar-color-3: var(--beam-fg-muted, var(--beam-ink-muted));
  --scalar-color-accent: var(--beam-accent, var(--beam-green));
  --scalar-border-color: var(--beam-border, var(--beam-line));
  --scalar-font: var(--beam-font-sans, inherit);
  --scalar-font-code: var(--beam-font-mono, ui-monospace, monospace);
  --scalar-sidebar-background-1: var(--beam-paper, var(--beam-paper-raised));
  --scalar-sidebar-color-1: var(--beam-fg, var(--beam-ink));
  --scalar-sidebar-color-2: var(--beam-fg-muted, var(--beam-ink-muted));
  --scalar-sidebar-border-color: var(--beam-border, var(--beam-line));
  --scalar-sidebar-item-hover-background: var(--beam-surface-2, var(--beam-muted));
  --scalar-sidebar-item-active-background: var(--beam-surface-2, var(--beam-muted));
  --scalar-sidebar-color-active: var(--beam-accent, var(--beam-green));
  --scalar-sidebar-search-background: var(--beam-paper-raised, var(--beam-paper));
  --scalar-sidebar-search-border-color: var(--beam-border, var(--beam-line));
}

/* Scalar forces every descendant of a property description onto color-2 with !important. Enum prose
   contains inline code such as "fixed" and "to_target"; Beam's translucent muted ink falls below AA
   on those chips in light mode. Keep the prose muted, but put only its inline code on primary ink. */
.scalar-app .property-description :not(pre) > code {
  color: var(--scalar-color-1) !important;
}`;

/** Curation, not palette: our MCP server has its own docs page, so hide Scalar's MCP affordance. */
const HIDE_MCP_LAYER_CSS = '.scalar-mcp-layer { display: none !important; }';

/** Third-party vendor chrome is not part of a host's documentation navigation. */
const HIDE_SCALAR_VENDOR_CHROME_CSS =
    '.scalar-app aside a[href="https://www.scalar.com"] { display: none !important; }';

/** In-flight/loaded script loads, deduped by URL so N references on a page fetch once. */
const scriptLoads = new Map<string, Promise<void>>();

function loadScript(url: string): Promise<void> {
    const existing = scriptLoads.get(url);
    if (existing) return existing;

    const load = new Promise<void>((resolve, reject) => {
        const script = document.createElement('script');
        script.src = url;
        script.async = true;
        if (url === SCALAR_CDN_URL) {
            script.setAttribute('integrity', SCALAR_CDN_INTEGRITY);
            script.setAttribute('crossorigin', 'anonymous');
        }
        script.addEventListener('load', () => resolve());
        script.addEventListener('error', () => {
            scriptLoads.delete(url);
            reject(new Error(`beam-docs ApiReference: failed to load the spec renderer from ${url}.`));
        });
        document.head.appendChild(script);
    });

    scriptLoads.set(url, load);
    return load;
}

function globalFactory(): ApiReferenceFactory | undefined {
    const scalar = (globalThis as { Scalar?: { createApiReference?: ApiReferenceFactory } }).Scalar;
    return scalar?.createApiReference;
}

export type ApiReferenceProps = {
    /** The OpenAPI document URL — typically the host's own `beam/openapi.json` (ADR-0211). */
    specUrl: string;
    /**
     * Injected renderer factory. Supply it (from a host-installed `@scalar/api-reference`) and the
     * component never touches the network for its renderer — the air-gapped / CSP-strict path.
     */
    createApiReference?: ApiReferenceFactory;
    /** Where to load the renderer from when no factory is injected. Defaults to {@link SCALAR_CDN_URL}. */
    scriptUrl?: string;
    /** Renderer theme name. Defaults to `default` — a renderer preset, not a beam palette. */
    theme?: string;
    /** Host theme CSS (fonts, accent colors). The package contributes no palette of its own. */
    customCss?: string;
    /** Keep the MCP-layer curation. Default `true`; set `false` to let the renderer show it. */
    hideMcpLayer?: boolean;
    /** Escape hatch: extra renderer configuration, shallow-merged last. */
    configuration?: Record<string, unknown>;
    /** Called when the renderer cannot be loaded, so a host can log or swap in a fallback. */
    onError?: (error: unknown) => void;
    /** A successful, server-selected Registry link. Explicit null suppresses link discovery. */
    registryUrl?: string | null;
    /** Optional server-policy endpoint. configureDocs() supplies the package endpoint. */
    registryLinkEndpoint?: string | null;
    /** Decoded-JSON transport used only for the Registry link, never for the Scalar renderer. */
    transport?: DocsTransport;
    className?: string;
    style?: CSSProperties;
};

export function ApiReference({
    specUrl,
    createApiReference,
    scriptUrl = SCALAR_CDN_URL,
    theme = 'default',
    customCss,
    hideMcpLayer = true,
    configuration,
    onError,
    registryUrl,
    registryLinkEndpoint,
    transport,
    className,
    style,
}: ApiReferenceProps) {
    const mount = useRef<HTMLDivElement | null>(null);
    const docs = docsConfiguration();
    // The reference follows the ONE appearance (DM5): Scalar reads its mode once at mount, so a flip remounts it.
    const { resolvedAppearance } = useAppearance();
    const endpoint = registryLinkEndpoint === undefined ? docs.registryLinkEndpoint : registryLinkEndpoint;
    const fetcher = transport ?? docs.transport ?? fetchDocs;
    const [loadedLink, setLoadedLink] = useState<{ endpoint: string; transport: DocsTransport; url: string | null } | null>(null);
    const link = registryUrl !== undefined ? scalarRegistryUrl(registryUrl)
        : loadedLink?.endpoint === endpoint && loadedLink.transport === fetcher ? loadedLink.url : null;

    useEffect(() => {
        if (registryUrl !== undefined || !endpoint) return;
        const controller = new AbortController();
        setLoadedLink(null);
        fetchRegistryLink(endpoint, fetcher, controller.signal)
            .then((url) => {
                if (!controller.signal.aborted) setLoadedLink({ endpoint, transport: fetcher, url });
            })
            .catch(() => {
                // An optional publication link never replaces or blocks the local reference.
                if (!controller.signal.aborted) setLoadedLink(null);
            });
        return () => controller.abort();
    }, [endpoint, fetcher, registryUrl]);

    useEffect(() => {
        let cancelled = false;
        const element = mount.current;
        if (!element) return;

        const css = [BEAM_SCALAR_CSS, HIDE_SCALAR_VENDOR_CHROME_CSS, hideMcpLayer ? HIDE_MCP_LAYER_CSS : null, customCss]
            .filter(Boolean)
            .join('\n');

        const render = (factory: ApiReferenceFactory) => {
            if (cancelled) return;
            factory(element, {
                url: specUrl,
                theme,
                ...(css ? { customCss: css } : {}),
                // The appearance is OURS (forcing it also hides Scalar's own toggle), and Scalar's Ask AI and developer
                // toolbar stay off unless a host opts in through `configuration` (DM5; Scalar turns both on for any
                // `.test`/`localhost` host by itself).
                forceDarkModeState: resolvedAppearance,
                agent: { disabled: true },
                showDeveloperTools: 'never',
                ...configuration,
            });
        };

        // A configured loader is the host's statement of WHICH Scalar to run; when it fails there is no silent CDN
        // fallback (the flagship ships a patched build for OpenAPI 3.2 tag parents).
        const loader = createApiReference ? undefined : docs.loadApiReference;
        if (loader) {
            loader()
                .then(render)
                .catch((error: unknown) => {
                    if (!cancelled) onError?.(error);
                });
            return () => {
                cancelled = true;
                element.replaceChildren();
            };
        }

        const injected = createApiReference ?? docs.createApiReference ?? globalFactory();
        if (injected) {
            render(injected);
        } else {
            loadScript(scriptUrl)
                .then(() => {
                    const factory = globalFactory();
                    if (!factory) {
                        throw new Error(
                            'beam-docs ApiReference: the renderer script loaded but exposed no factory.',
                        );
                    }
                    render(factory);
                })
                .catch((error: unknown) => {
                    if (!cancelled) onError?.(error);
                });
        }

        return () => {
            cancelled = true;
            // The renderer owns the subtree it mounted; clearing it is the portable teardown (Scalar
            // exposes no stable destroy across versions, and React never owned these children).
            element.replaceChildren();
        };
    }, [
        specUrl,
        createApiReference,
        scriptUrl,
        theme,
        customCss,
        hideMcpLayer,
        configuration,
        onError,
        resolvedAppearance,
        docs.createApiReference,
        docs.loadApiReference,
    ]);

    // `data-beam-full-bleed` is declared by the COMPONENT, not by each host's wrapper. A reference is a
    // whole application — its own sidebar, search and request panes — never an article, so it wants the
    // page's full width on every host that will ever render it. Ticket 07 found it boxed inside the
    // article measure on `splicewire/www` and fixed it there with a host-local wrapper div; a fresh
    // `laravel-beam-starter` then reproduced the identical defect, because a fact true of the component
    // everywhere was being restated per host (beam-docs-satellite ticket 11). A host still decides what
    // full-bleed MEANS — the attribute is only the declaration.
    return (
        <div data-beam-full-bleed="">
            {link && (
                <p data-beam-docs-registry-link="" style={{ margin: 0, padding: '0.75rem 1rem' }}>
                    <a href={link} target="_blank" rel="noopener noreferrer">View published API in Scalar Registry</a>
                </p>
            )}
            <div ref={mount} className={className} style={style} data-beam-ux-api-reference={specUrl} />
        </div>
    );
}
